177	// 损坏并拒绝读取：多出的右花括号/右方括号不能被忽略，后面拼接另一段即使
178	// 本身合法的 JSON 也不能作为第二份记录，普通文字或没写完的 JSON 片段同样
179	// 拒绝。错误信息要能定位文件并说明尾部有多余内容，且文件原始字节（含多余
180	// 符号、文字与空白）必须原样保留。
181	func TestLoadRejectsTrailingGarbage(t *testing.T) {
182		// 开头是一份结构、引用完全合法的记录，不能因为它能解析就接受整份文件。
183		good := `{"version":1,"students":[{"id":"s1"}],` +
184			`"courses":[{"id":"c1","name":"数学","credit":4,"open":true}],` +
185			`"requirements":[{"id":"r1","student":"s1","course":"c1"}],` +
186			`"enrollments":[],"waivers":[],"nextResultSeq":0}`
187	
188		cases := map[string]string{
189			"尾部多余右花括号":     good + "}",
190			"尾部多余右方括号":     good + "]",
191			"括号前带空白仍拒绝":    good + " \t }",
192			"尾部拼接第二份JSON":  good + good,
193			"尾部拼接空数组":      good + "[]",
194			"尾部拼接空对象":      good + "{}",
195			"尾部拼接数字":       good + " 42",
196			"尾部拼接字符串":      good + ` "x"`,
197			"尾部普通文字":       good + "普通文字",
198			"尾部未写完的对象片段":   good + ` {"version":`,
199			"尾部未写完的数组片段":   good + " [1, 2,",
200			"尾部多余花括号后再跟空白": good + "}\n  \t\r\n",
201		}
202		for name, content := range cases {
203			t.Run(name, func(t *testing.T) {
204				path := filepath.Join(t.TempDir(), "records.json")
205				if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
206					t.Fatal(err)
207				}
208				s, existed, err := Load(path)
209				if err == nil {
210					t.Fatalf("%s：尾部有多余内容应判损坏并拒绝，却得到 store=%v", name, s)
211				}
212				if !existed {
213					t.Fatalf("%s：损坏文件应标记为已存在", name)
214				}
215				msg := err.Error()
216				if !strings.Contains(msg, path) {
217					t.Fatalf("%s：错误信息应点名问题文件，得到：%v", name, err)
218				}
219				if !strings.Contains(msg, "内容损坏") || !strings.Contains(msg, "完整记录") {
220					t.Fatalf("%s：错误信息应说明完整记录之后有多余内容，得到：%v", name, err)
221				}
222				got, readErr := os.ReadFile(path)
223				if readErr != nil {
224					t.Fatal(readErr)
225				}
226				if string(got) != content {
227					t.Fatalf("%s：拒绝读取不得截断或改写原文件\nwant=%q\n got=%q", name, content, got)
228				}
229			})
230		}
231	}
