11	//
12	// 旧实现把复合键拼成 student + "\x00" + id 作为 map 键。编号本身允许是
13	// JSON 解码后的任意文字，含 U+0000 也合法；于是 ("s", "x\x00r") 与
14	// ("s\x00x", "r") 两个不同归属会生成同一个拼接键，造成：
15	//   - 两名学生各自合法的要求/修读/免修在读取时互相顶替，被判重复而拒绝整份
16	//     合法文件；
17	//   - 某学生的有效免修找不到本人要求时，顺着冲突键借用另一名学生的同键要求
18	//     变得“合法”，核对串到他人的课程学分。
19	//
20	// 修复后复合键是两字段结构体，编号原文（含空字符）逐字保留，以下用例固定
21	// 这些结论。
22	
23	// nulOwnersRecord 构造题目所述两名学生的完整合法记录：
24	//   - 学生 "s"：要求 "x\x00r" 指向 4 学分课程 c4，有一条通过修读与一份
25	//     有效免修；
26	//   - 学生 "s\x00x"：要求 "r" 指向 3 学分课程 c3，另有一条通过修读与一份
27	//     有效免修。
28	//
29	// 修读与免修编号同样取成会在旧拼接键下互相冲突的文字（("s","x\x00e") 对
30	// ("s\x00x","e")、("s","x\x00w") 对 ("s\x00x","w")），一并固定归属隔离。
31	func nulOwnersRecord() *fileData {
32		return &fileData{
33			Version: recordVersion,
34			Courses: []*Course{
35				{ID: "c4", Name: "高等数学", Credit: 4, Open: true},
36				{ID: "c3", Name: "线性代数", Credit: 3, Open: true},
37			},
38			Students: []*Student{{ID: "s"}, {ID: "s\x00x"}},
39			Requirements: []*Requirement{
40				{ID: "x\x00r", StudentID: "s", CourseID: "c4"},
41				{ID: "r", StudentID: "s\x00x", CourseID: "c3"},
42			},
43			Enrollments: []*Enrollment{
44				{ID: "x\x00e", StudentID: "s", ReqID: "x\x00r", Term: "2024春",
45					Result: Passed, ResultSeq: 1},
46				{ID: "e", StudentID: "s\x00x", ReqID: "r", Term: "2024春",
47					Result: Passed, ResultSeq: 2},
48			},
49			Waivers: []*Waiver{
50				{ID: "x\x00w", StudentID: "s", ReqID: "x\x00r",
51					Basis: "s 的竞赛获奖", Status: WaiverApproved},
52				{ID: "w", StudentID: "s\x00x", ReqID: "r",
53					Basis: "s\x00x 的外校修读证明", Status: WaiverApproved},
54			},
55			NextResultSeq: 2,
56		}
57	}
58	
59	// assertNulOwnersSeparated 核对两名学生的要求、修读、免修与学分完全各归各。
60	func assertNulOwnersSeparated(t *testing.T, s *Store) {
61		t.Helper()
62	
63		// 要求查询：本人的查得到，对方的同拼接键要求查不到，指针互不相同。
64		rS := s.Requirement("s", "x\x00r")
65		rSX := s.Requirement("s\x00x", "r")
66		if rS == nil || rSX == nil || rS == rSX {
67			t.Fatalf("两名学生的要求应各自独立存在，得到 %p 与 %p", rS, rSX)
68		}
69		if rS.CourseID != "c4" || rSX.CourseID != "c3" {
70			t.Fatalf("要求课程归属错误：s 应指 c4、s\\x00x 应指 c3，得到 %s、%s",
71				rS.CourseID, rSX.CourseID)
72		}
73		if got := s.Requirement("s", "r"); got != nil {
74			t.Fatalf("学生 s 名下不存在要求 r（那是 s\\x00x 的），却得到 %+v", got)
75		}
76		if got := s.Requirement("s\x00x", "x\x00r"); got != nil {
77			t.Fatalf("学生 s\\x00x 名下不存在要求 x\\x00r（那是 s 的），却得到 %+v", got)
78		}
79		if reqs := s.AllRequirements(); len(reqs) != 2 {
80			t.Fatalf("应保留两项要求，不得合并，得到 %d 项：%+v", len(reqs), reqs)
81		}
82	
83		// 修读与免修编号同样按所属学生隔离，交叉查询必须全部落空。
84		if e := s.Enrollment("s", "x\x00e"); e == nil || e.ReqID != "x\x00r" {
85			t.Fatalf("s 的修读 x\\x00e 应指向本人要求，得到 %+v", e)
86		}
87		if e := s.Enrollment("s\x00x", "e"); e == nil || e.ReqID != "r" {
88			t.Fatalf("s\\x00x 的修读 e 应指向本人要求 r，得到 %+v", e)
89		}
90		if s.Enrollment("s", "e") != nil || s.Enrollment("s\x00x", "x\x00e") != nil {
91			t.Fatal("修读编号交叉查询不应串到另一名学生")
92		}
93		wS := s.Waiver("s", "x\x00w")
94		wSX := s.Waiver("s\x00x", "w")
95		if wS == nil || wSX == nil || wS == wSX {
96			t.Fatalf("两名学生的有效免修应各自独立，得到 %p 与 %p", wS, wSX)
97		}
98		if s.Waiver("s", "w") != nil || s.Waiver("s\x00x", "x\x00w") != nil {
99			t.Fatal("免修编号交叉查询不应串到另一名学生")
100		}
101	
102		// 核对结果：s 凭本人有效免修得 4 学分，s\x00x 得 3 学分；有有效免修时
103		// 以免修说明来源，通过修读只作历史、不重复计学分。
104		rep := s.CheckStudent("s")
105		if rep.TotalCredits != 4 || len(rep.Unmet) != 0 {
106			t.Fatalf("s 应凭本人免修满足要求、计 4 学分，得到学分=%d 未满足=%v",
107				rep.TotalCredits, rep.Unmet)
108		}
109		if len(rep.Requirements) != 1 {
110			t.Fatalf("s 名下应只有一项要求，得到 %+v", rep.Requirements)
111		}
112		st := rep.Requirements[0]
113		if st.Req.ID != "x\x00r" || st.Course.ID != "c4" || st.Course.Credit != 4 ||
114			st.Source != "waiver" || st.WaiverID != "x\x00w" ||
115			len(st.PassedEnrollmentIDs) != 1 || st.PassedEnrollmentIDs[0] != "x\x00e" {
116			t.Fatalf("s 的核对依据应全部来自本人记录，得到 %+v（历史 %v）",
117				st, st.PassedEnrollmentIDs)
118		}
119		if len(rep.RejectedWaivers) != 0 || len(rep.RevokedWaivers) != 0 {
120			t.Fatalf("s 不应有失效免修历史，得到 %+v / %v",
121				rep.RejectedWaivers, rep.RevokedWaivers)
122		}
123	
124		rep = s.CheckStudent("s\x00x")
125		if rep.TotalCredits != 3 || len(rep.Unmet) != 0 {
126			t.Fatalf("s\\x00x 应凭本人免修满足要求、计 3 学分，得到学分=%d 未满足=%v",
127				rep.TotalCredits, rep.Unmet)
128		}
129		if len(rep.Requirements) != 1 {
130			t.Fatalf("s\\x00x 名下应只有一项要求，得到 %+v", rep.Requirements)
131		}
132		st = rep.Requirements[0]
133		if st.Req.ID != "r" || st.Course.ID != "c3" || st.Course.Credit != 3 ||
134			st.Source != "waiver" || st.WaiverID != "w" ||
135			len(st.PassedEnrollmentIDs) != 1 || st.PassedEnrollmentIDs[0] != "e" {
136			t.Fatalf("s\\x00x 的核对依据应全部来自本人记录，得到 %+v（历史 %v）",
137				st, st.PassedEnrollmentIDs)
138		}
139	
140		// 免修历史各自只含本人申请，查看历史保留含空字符的编号原文与依据。
141		ws := s.Waivers("s")
142		if len(ws) != 1 || ws[0] != wS || ws[0].ReqID != "x\x00r" ||
143			ws[0].Basis != "s 的竞赛获奖" {
144			t.Fatalf("s 的免修历史应只保留本人 x\\x00w 申请，得到 %+v", ws)
145		}
146		wsx := s.Waivers("s\x00x")
147		if len(wsx) != 1 || wsx[0] != wSX || wsx[0].ReqID != "r" ||
148			wsx[0].Basis != "s\x00x 的外校修读证明" {
149			t.Fatalf("s\\x00x 的免修历史应只保留本人 w 申请，得到 %+v", wsx)
150		}
151	}
152	
153	// TestLoadNullContainingIDsKeepOwnership 题目主场景：含 U+0000 的两组
154	// 归属在旧拼接键下完全同键，合法文件必须正常打开，两人核对分别得到
155	// 4 学分与 3 学分；保存后重开编号原文与归属全部保留。
156	func TestLoadNullContainingIDsKeepOwnership(t *testing.T) {
157		path, raw := writeRecord(t, nulOwnersRecord())
158	
159		s, existed, err := Load(path)
160		if err != nil || !existed {
161			t.Fatalf("两名学生的合法记录必须正常读取，不得误报要求/免修编号重复，existed=%v err=%v",
162				existed, err)
163		}
164		assertNulOwnersSeparated(t, s)
165	
166		// 只读核对不得改动文件。
167		if got, readErr := os.ReadFile(path); readErr != nil || string(got) != string(raw) {
168			t.Fatalf("只读访问不得改写原文件，readErr=%v", readErr)
169		}
170	
171		// 重新保存再加载：空字符必须逐字保留，不能为消除冲突删改编号或合并记录。
172		path2 := filepath.Join(t.TempDir(), "records.json")
173		if err := s.Save(path2); err != nil {
174			t.Fatalf("Save: %v", err)
175		}
176		reloaded, existed, err := Load(path2)
177		if err != nil || !existed {
178			t.Fatalf("含空字符编号的记录重存后应可再次加载，existed=%v err=%v", existed, err)
179		}
180		assertNulOwnersSeparated(t, reloaded)
181		for _, r := range reloaded.AllRequirements() {
182			if !strings.Contains(r.StudentID+r.ID, "\x00") {
183				t.Fatalf("重存后编号原文中的空字符丢失：%+v", r)
184			}
185		}
186	}
187	
188	// TestLoadApprovedWaiverCannotBorrowNullConfusableRequirement 文件里只有
189	// 学生 "s\x00x" 名下的要求 "r"，却有一份属于 "s"、声称取代 "x\x00r" 的
190	// 有效免修：旧实现顺着相同拼接键借用第二名学生的要求让它合法。修复后
191	// 必须明确报告免修目标不属于该学生或不存在，按损坏文件处理，原文件保留。
192	func TestLoadApprovedWaiverCannotBorrowNullConfusableRequirement(t *testing.T) {
193		d := &fileData{
194			Version: recordVersion,
195			Courses: []*Course{
196				{ID: "c4", Name: "高等数学", Credit: 4, Open: true},
197				{ID: "c3", Name: "线性代数", Credit: 3, Open: true},
198			},
199			Students: []*Student{{ID: "s"}, {ID: "s\x00x"}},
200			Requirements: []*Requirement{
201				// 只有第二名学生的要求 r -> c3；s 名下没有任何要求。
202				{ID: "r", StudentID: "s\x00x", CourseID: "c3"},
203			},
204			Waivers: []*Waiver{
205				// s\x00x 本人的有效免修：合法。
206				{ID: "w", StudentID: "s\x00x", ReqID: "r",
207					Basis: "s\x00x 本人的依据", Status: WaiverApproved},
208				// s 声称取代 x\x00r：s 名下不存在该要求，不能借用 s\x00x 的 r。
209				{ID: "x\x00w", StudentID: "s", ReqID: "x\x00r",
210					Basis: "s 的材料", Status: WaiverApproved},
211			},
212		}
213		path, raw := writeRecord(t, d)
214	
215		s, existed, err := Load(path)
216		if err == nil {
217			t.Fatalf("有效免修借用他人同键要求时必须整份拒绝，却得到 store=%v", s)
218		}
219		if !existed {
220			t.Fatalf("应按已有损坏文件处理（existed=true），existed=%v", existed)
221		}
222		msg := err.Error()
223		for _, want := range []string{"内容损坏", "s", "x\x00w", "x\x00r", "不存在或不属于该学生"} {
224			if !strings.Contains(msg, want) {
225				t.Fatalf("错误应明确报告目标要求不属于该学生或不存在（缺 %q），得到：%v", want, err)
226			}
227		}
228		if got, readErr := os.ReadFile(path); readErr != nil || string(got) != string(raw) {
229			t.Fatalf("拒绝读取不得改写原文件，readErr=%v", readErr)
230		}
231	}
232	
233	// TestLoadNullConfusableRejectedWaiverKeptAsHistory 被拒绝的申请仍可记录
234	// 不存在的目标：s 一份指向 "x\x00r"（s 名下并无此要求，只有 s\x00x 的 r）
235	// 的 rejected 申请必须原样保留（编号、依据、原因），不获得学分，也不变成
236	// 有效免修；s\x00x 本人的核对不受影响。
237	func TestLoadNullConfusableRejectedWaiverKeptAsHistory(t *testing.T) {
238		d := &fileData{
239			Version: recordVersion,
240			Courses: []*Course{
241				{ID: "c3", Name: "线性代数", Credit: 3, Open: true},
242			},
243			Students: []*Student{{ID: "s"}, {ID: "s\x00x"}},
244			Requirements: []*Requirement{
245				{ID: "r", StudentID: "s\x00x", CourseID: "c3"},
246			},
247			Waivers: []*Waiver{
248				{ID: "w", StudentID: "s\x00x", ReqID: "r",
249					Basis: "s\x00x 本人的依据", Status: WaiverApproved},
250				{ID: "x\x00w", StudentID: "s", ReqID: "x\x00r", Basis: "s 的材料",
251					Status: WaiverRejected, Reason: "目标要求 x\x00r 不存在或不属于该学生"},
252			},
253		}
254		path, _ := writeRecord(t, d)
255	
256		s, _, err := Load(path)
257		if err != nil {
258			t.Fatalf("被拒绝申请允许指向不存在的目标，记录应正常打开：%v", err)
259		}
260	
261		rep := s.CheckStudent("s")
262		if rep.TotalCredits != 0 || len(rep.Unmet) != 0 || len(rep.Requirements) != 0 {
263			// s 名下没有要求：没有未满足项，也没有学分。
264			t.Fatalf("s 无要求无有效免修，应 0 学分，得到 %+v", rep)
265		}
266		if len(rep.RejectedWaivers) != 1 {
267			t.Fatalf("s 的被拒绝申请应保留在历史中，得到 %+v", rep.RejectedWaivers)
268		}
269		rj := rep.RejectedWaivers[0].Waiver
270		if rj.ID != "x\x00w" || rj.ReqID != "x\x00r" || rj.Basis != "s 的材料" ||
271			rj.Status != WaiverRejected {
272			t.Fatalf("被拒绝申请应原样保留编号/目标/依据，得到 %+v", rj)
273		}
274	
275		// s\x00x 本人的有效免修与 3 学分不受 s 的失效历史影响。
276		rep2 := s.CheckStudent("s\x00x")
277		if rep2.TotalCredits != 3 || len(rep2.RejectedWaivers) != 0 {
278			t.Fatalf("s\\x00x 应仍凭本人 w 得 3 学分且无拒绝历史，得到 %+v", rep2)
279		}
280	}
281	
282	// TestLoadNullConfusableRevokedWaiverStillNeedsOwnRequirement 已撤销免修
283	// 同样必须保留对本人真实要求的引用：s 的已撤销免修指向并不存在于 s 名下的
284	// "x\x00r"（只有 s\x00x 的 r）时，整份文件判损坏，不能借用他人要求合法化。
285	func TestLoadNullConfusableRevokedWaiverStillNeedsOwnRequirement(t *testing.T) {
286		d := &fileData{
287			Version: recordVersion,
288			Courses: []*Course{
289				{ID: "c3", Name: "线性代数", Credit: 3, Open: true},
290			},
291			Students: []*Student{{ID: "s"}, {ID: "s\x00x"}},
292			Requirements: []*Requirement{
293				{ID: "r", StudentID: "s\x00x", CourseID: "c3"},
294			},
295			Waivers: []*Waiver{
296				{ID: "x\x00w", StudentID: "s", ReqID: "x\x00r", Basis: "s 的旧材料",
297					Status: WaiverRevoked, Reason: "材料无法核实"},
298			},
299		}
300		path, raw := writeRecord(t, d)
301	
302		s, existed, err := Load(path)
303		if err == nil {
304			t.Fatalf("已撤销免修借用他人同键要求时必须整份拒绝，却得到 store=%v", s)
305		}
306		if !existed {
307			t.Fatalf("应按已有损坏文件处理，existed=%v", existed)
308		}
309		msg := err.Error()
310		if !strings.Contains(msg, "内容损坏") ||
311			!strings.Contains(msg, "目标要求无效") || !strings.Contains(msg, "x\x00r") {
312			t.Fatalf("错误应说明已撤销免修的目标要求在本人名下无效，得到：%v", err)
313		}
314		if got, readErr := os.ReadFile(path); readErr != nil || string(got) != string(raw) {
315			t.Fatalf("拒绝读取不得改写原文件，readErr=%v", readErr)
316		}
317	}
318	
319	// TestNullContainingIDsInMemoryOwnership 经正常登记/申请流程产生的含空字符
320	// 编号同样按归属隔离：两项要求各自新建成功（不是幂等命中也不是重复拒绝），
321	// 各自的有效免修只认本人要求；顺着冲突键替他人要求申请免修必须被拒绝，
322	// 同一学生名下真正的重复要求仍按原规则拒绝。
323	func TestNullContainingIDsInMemoryOwnership(t *testing.T) {
324		s := NewStore()
325		mustCourse(t, s, "c4", "高等数学", 4)
326		mustCourse(t, s, "c3", "线性代数", 3)
327		mustStudent(t, s, "s")
328		mustStudent(t, s, "s\x00x")
329	
330		r1, a, err := s.AddRequirement("s", "x\x00r", "c4")
331		if err != nil || a != ActionCreated {
332			t.Fatalf("s 登记 x\\x00r 应新建成功，得到 %+v action=%v err=%v", r1, a, err)
333		}
334		r2, a, err := s.AddRequirement("s\x00x", "r", "c3")
335		if err != nil || a != ActionCreated {
336			t.Fatalf("s\\x00x 登记 r 应是独立的新建，不能与 s 的 x\\x00r 混为一项，得到 %+v action=%v err=%v",
337				r2, a, err)
338		}
339		if r1 == r2 {
340			t.Fatal("两项要求应是不同记录")
341		}
342	
343		// 各自重复登记本人要求：幂等返回原记录。
344		if got, a, err := s.AddRequirement("s", "x\x00r", "c4"); err != nil ||
345			a != ActionExisted || got != r1 {
346			t.Fatalf("s 重复登记本人要求应幂等，得到 %+v action=%v err=%v", got, a, err)
347		}
348		if got, a, err := s.AddRequirement("s\x00x", "r", "c3"); err != nil ||
349			a != ActionExisted || got != r2 {
350			t.Fatalf("s\\x00x 重复登记本人要求应幂等，得到 %+v action=%v err=%v", got, a, err)
351		}
352	
353		// 同一学生就同一课程换编号再建要求：仍按原规则拒绝。
354		if _, _, err := s.AddRequirement("s", "other", "c4"); err == nil ||
355			!strings.Contains(err.Error(), "重复建立") {
356			t.Fatalf("同一学生就同一课程重复建立要求应拒绝，得到 %v", err)
357		}
358	
359		// s\x00x 不能替 s 的 x\x00r 申请免修：旧实现会顺着同键要求误判目标存在。
360		w, a, err := s.ApplyWaiver("s\x00x", "x\x00r", "wbad", "借来的依据")
361		if err != nil || a != ActionCreated || w.Status != WaiverRejected {
362			t.Fatalf("替他人同键要求申请免修应被拒绝并留历史，得到 %+v action=%v err=%v", w, a, err)
363		}
364		if !strings.Contains(w.Reason, "不存在或不属于该学生") {
365			t.Fatalf("拒绝原因应说明目标要求不属于该学生，得到 %q", w.Reason)
366		}
367	
368		// 两人各自指向本人要求的免修都正常生效，核对分别得到本人课程学分。
369		if w, a, err := s.ApplyWaiver("s", "x\x00r", "x\x00w", "s 的依据"); err != nil ||
370			a != ActionCreated || w.Status != WaiverApproved {
371			t.Fatalf("s 为本人 x\\x00r 申请免修应生效，得到 %+v action=%v err=%v", w, a, err)
372		}
373		if w, a, err := s.ApplyWaiver("s\x00x", "r", "w", "s\x00x 的依据"); err != nil ||
374			a != ActionCreated || w.Status != WaiverApproved {
375			t.Fatalf("s\\x00x 为本人 r 申请免修应生效，得到 %+v action=%v err=%v", w, a, err)
376		}
377		if rep := s.CheckStudent("s"); rep.TotalCredits != 4 ||
378			len(rep.RejectedWaivers) != 0 {
379			t.Fatalf("s 应只有本人要求的 4 学分，被拒绝的是 s\\x00x 的申请，得到 %+v", rep)
380		}
381		if rep := s.CheckStudent("s\x00x"); rep.TotalCredits != 3 {
382			t.Fatalf("s\\x00x 应只有本人要求的 3 学分，其被拒绝申请不计学分，得到 %+v", rep)
383		}
384	}
